class DefaultConfigProvider : DefaultConfigurationProvider {
    private lateinit var extensionsSpec: ExtensionsSpec

    override fun init(extensionsSpec: ExtensionsSpec) {
        this.extensionsSpec = extensionsSpec
    }

    override fun get(): Config = extensionsSpec.getDefaultConfiguration()

    override fun copy(targetLocation: Path) {
        Files.copy(configInputStream(extensionsSpec), targetLocation, StandardCopyOption.REPLACE_EXISTING)
    }
}

private fun configInputStream(extensionsSpec: ExtensionsSpec): InputStream {
    val outputStream = ByteArrayOutputStream()

    requireNotNull(DefaultConfigProvider::class.java.getSafeResourceAsStream("/default-detekt-config.yml"))
        .use { it.copyTo(outputStream) }

    ExtensionFacade(extensionsSpec.plugins).pluginLoader
        .getSafeResourcesAsStreams("config/config.yml")
        .forEach { inputStream ->
            outputStream.write('\n'.code)
            inputStream.use { it.copyTo(outputStream) }
        }

    return ByteArrayInputStream(outputStream.toByteArray())
}

private fun ClassLoader.getSafeResourcesAsStreams(name: String): Sequence<InputStream> =
    getResources(name)
        .asSequence()
        .map { it.openSafeStream() }

private fun ExtensionsSpec.getDefaultConfiguration(): Config = YamlConfig.load(configInputStream(this).reader())

fun ProcessingSpec.getDefaultConfiguration(): Config = extensionsSpec.getDefaultConfiguration()
package dev.detekt.core.rules

import dev.detekt.api.RuleSetProvider
import dev.detekt.api.internal.DefaultRuleSetProvider
import dev.detekt.core.ProcessingSettings
import dev.detekt.core.extensions.LIST_ITEM_SPACING
import dev.detekt.core.extractRuleName
import dev.detekt.tooling.api.spec.RulesSpec
import java.util.ServiceLoader

fun ProcessingSettings.createRuleProviders(): List<RuleSetProvider> {
    val ruleSetProviders = ServiceLoader.load(RuleSetProvider::class.java, pluginLoader)
        .filterNot { it.ruleSetId.value in spec.extensionsSpec.disabledExtensions }

    return when (val runPolicy = spec.rulesSpec.runPolicy) {
        RulesSpec.RunPolicy.NoRestrictions -> ruleSetProviders

        RulesSpec.RunPolicy.DisableDefaultRuleSets ->
            ruleSetProviders
                .filterNot { it is DefaultRuleSetProvider }

        is RulesSpec.RunPolicy.RestrictToSingleRule -> {
            val ruleSetId = runPolicy.ruleSetId
            val ruleId = runPolicy.ruleId
            val realProvider = requireNotNull(ruleSetProviders.find { it.ruleSetId == ruleSetId }) {
                "There was no rule set with id '$ruleSetId'."
            }
            val ruleName = requireNotNull(extractRuleName(ruleId)) {
                "There was not rule '$ruleId' in rule set '$ruleSetId'."
            }
            listOf(SingleRuleProvider(ruleName, realProvider))
        }
    }
        .also {
            debug {
                "Registered rule sets: $LIST_ITEM_SPACING" +
                    it.joinToString(LIST_ITEM_SPACING) { it.javaClass.canonicalName }
            }
        }
}

