23:/**
24: * Settings to be used by the detekt engine.
25: *
26: * Always close the settings as dispose the Kotlin compiler and detekt class loader.
27: * If using a custom executor service be aware that detekt won't shut it down after use!
28: */
29:class ProcessingSettings private constructor(
30:    val spec: ProcessingSpec,
31:    override val config: Config,
32:    val monitor: PerformanceMonitor,
33:    private val environmentAware: EnvironmentFacade,
34:) : AutoCloseable,
35:    LoggingAware by LoggingFacade(spec.loggingSpec),
36:    PropertiesAware by PropertiesFacade(),
37:    EnvironmentAware by environmentAware,
38:    ClassloaderAware by ExtensionFacade(spec.extensionsSpec.plugins),
39:    SetupContext {
40:
41:    override val configUris: Collection<URI> = spec.configSpec.extractUris()
42:
43:    override val basePath: Path = spec.projectSpec.basePath
44:
45:    /**
46:     * Sharable thread pool between parsing and analysis phase.
47:     */
48:    val taskPool: TaskPool by lazy { TaskPool(spec.executionSpec.executorService) }
49:
50:    constructor(spec: ProcessingSpec, config: Config, monitor: PerformanceMonitor) : this(
51:        spec,
52:        config,
53:        monitor,
54:        EnvironmentFacade(spec.projectSpec, spec.compilerSpec, spec.loggingSpec),
55:    )
56:
57:    override fun close() {
58:        closeQuietly(taskPool)
59:        environmentAware.close()
60:        closeLoaderIfNeeded()
61:    }
62:}
63:
64:private fun ConfigSpec.extractUris(): Collection<URI> {
65:    fun initFileSystem(uri: URI) {
66:        runCatching {
67:            try {
68:                FileSystems.getFileSystem(uri)
69:            } catch (_: FileSystemNotFoundException) {
70:                FileSystems.newFileSystem(uri, mapOf("create" to "true"))
71:            }
72:        }
73:    }
74:
75:    val pathUris = configPaths.map(Path::toUri)
76:    val resourceUris = resources.map(URL::toURI)
77:    resourceUris.forEach(::initFileSystem)
78:    return resourceUris + pathUris
79:}
